<?php
// Integration checks. Run only against the isolated development router on port 8097.
$base='http://127.0.0.1:8097';$cookie=tempnam(sys_get_temp_dir(),'parthvi-manager-');$passed=0;
function req($path,$data=null){global $base,$cookie;$c=curl_init($base.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEJAR=>$cookie,CURLOPT_COOKIEFILE=>$cookie]);if($data!==null){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,$data);}$raw=curl_exec($c);if($raw===false)throw new Exception(curl_error($c));$n=curl_getinfo($c,CURLINFO_HEADER_SIZE);$code=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return ['status'=>$code,'body'=>substr($raw,$n),'headers'=>substr($raw,0,$n)];}
function ok($value,$message){global $passed;if(!$value)throw new Exception('FAIL: '.$message);$passed++;echo "PASS: $message\n";}
function editor($html){$doc=new DOMDocument();@$doc->loadHTML($html);$xp=new DOMXPath($doc);$out=[];foreach($xp->query('//form[contains(@class,"editor-form")]//input | //form[contains(@class,"editor-form")]//textarea') as $f){$name=$f->getAttribute('name');$type=$f->getAttribute('type');if(!$name||in_array($type,['file','submit'])||($type==='checkbox'&&!$f->hasAttribute('checked')))continue;$out[$name]=$f->nodeName==='textarea'?$f->textContent:$f->getAttribute('value');}return $out;}
function csrf($html){preg_match('/name="csrf" value="([a-f0-9]+)"/',$html,$m);return $m[1]??'';}
function page_form($slug){return editor(req('/admin/index.php?section=pages&slug='.$slug)['body']);}
function item_id($html,$name){$d=new DOMDocument();@$d->loadHTML($html);$xp=new DOMXPath($d);foreach($xp->query('//tr') as $r)if(str_contains($r->textContent,$name)){foreach($xp->query('.//a[contains(@href,"edit=")]',$r) as $a){parse_str(parse_url($a->getAttribute('href'),PHP_URL_QUERY),$q);return $q['edit'];}}return null;}
try{
 $r=req('/admin/login.php');$r=req('/admin/login.php',['csrf'=>csrf($r['body']),'email'=>'admin@gmail.com','password'=>getenv('PARTHVI_TEST_PASSWORD')?:'123456']);ok($r['status']===302,'Admin sign-in');
 foreach(['index','about','products','contact','certificates','privacy-policy','terms-and-conditions','site'] as $slug){$f=page_form($slug);ok(($f['slug']??'')===$slug&&isset($f['version']),'Working editor for '.$slug);}
 $f=page_form('index');$f['copy_copy_483cb724bb']='Managed introduction <script>test</script>';$r=req('/admin/index.php?section=pages&slug=index',$f);ok($r['status']===302,'Homepage introduction saves');$home=req('/')['body'];ok(str_contains($home,'Managed introduction &lt;script&gt;test&lt;/script&gt;'),'Managed text renders escaped');
 $f=page_form('index');unset($f['copy_show_steps']);req('/admin/index.php?section=pages&slug=index',$f);ok(!str_contains(req('/')['body'],'class="steps-grid"'),'Hide a homepage section');$f=page_form('index');$f['copy_show_steps']='1';req('/admin/index.php?section=pages&slug=index',$f);ok(str_contains(req('/')['body'],'class="steps-grid"'),'Restore a hidden section');
 preg_match('~class="hero-main-product"[^>]*\ssrc="([^"]+)"~',req('/')['body'],$beforeHero);
 $f=page_form('index');$f['copy_hero_main_image']=new CURLFile(dirname(__DIR__).'/assets/images/parthvi-exim-client-logo.png','image/png','hero.png');$r=req('/admin/index.php?section=pages&slug=index',$f);ok($r['status']===302,'Homepage image upload');preg_match('~class="hero-main-product"[^>]*\ssrc="([^"]+)"~',req('/')['body'],$afterHero);ok(isset($afterHero[1])&&$afterHero[1]!==($beforeHero[1]??'')&&req('/'.html_entity_decode($afterHero[1]))['status']===200,'Uploaded homepage image is used publicly');
 $f=page_form('about');$f['copy_copy_b415ab881d']='Managed Founder';$r=req('/admin/index.php?section=pages&slug=about',$f);ok($r['status']===302&&str_contains(req('/about')['body'],'Managed Founder'),'Founder profile is editable');
 $f=page_form('site');$f['copy_nav_home']='Start here';$f['copy_theme_primary']='#1c3864';$r=req('/admin/index.php?section=pages&slug=site',$f);ok($r['status']===302&&str_contains(req('/')['body'],'Start here'),'Navigation label is editable');ok(str_contains(req('/theme.php')['body'],'#1c3864'),'Brand colour controls the public stylesheet');
 $f=page_form('site');$f['copy_cta_link']='javascript:alert(1)';$r=req('/admin/index.php?section=pages&slug=site',$f);ok(str_contains($r['body'],'Use a page path'),'Unsafe button links rejected');$f=page_form('site');$f['copy_theme_primary']='not-a-colour';$r=req('/admin/index.php?section=pages&slug=site',$f);ok(str_contains($r['body'],'valid colour'),'Invalid colours rejected');
 $f=page_form('site');$f['copy_catalogue_file']=new CURLFile(dirname(__DIR__).'/assets/documents/parthvi-exim-product-catalogue.pdf','application/pdf','catalogue.pdf');$r=req('/admin/index.php?section=pages&slug=site',$f);ok($r['status']===302,'Full-size catalogue PDF upload');$home=req('/')['body'];ok((bool)preg_match('~href="assets/uploads/[a-f0-9]+\.pdf" download~',$home),'New catalogue is linked in the footer');
 $f=page_form('site');unset($f['copy_show_catalogue'],$f['copy_show_cta'],$f['copy_show_whatsapp']);req('/admin/index.php?section=pages&slug=site',$f);$home=req('/')['body'];ok(!str_contains($home,' download>')&&!str_contains($home,'class="fresh-cta"')&&!str_contains($home,'class="whatsapp-bubble"'),'Shared visibility switches work');
 $r=req('/admin/index.php?section=categories');$id=item_id($r['body'],'Dehydrated White Onion');ok((bool)$id,'Categories have an editor');$url='/admin/index.php?section=categories&edit='.$id;$f=editor(req($url)['body']);$f['name']='White Onion QA';$r=req($url,$f);ok($r['status']===302,'Rename category');ok(str_contains(req('/products/white-onion-flakes')['body'],'White Onion QA'),'Category rename updates product details');
 $f=editor(req($url)['body']);unset($f['published']);req($url,$f);ok(req('/products/white-onion-flakes')['status']===404,'Draft category hides its product routes');ok(!str_contains(req('/sitemap.xml')['body'],'products/white-onion-flakes'),'Draft category products are excluded from sitemap');$f=editor(req($url)['body']);$f['published']='1';req($url,$f);ok(req('/products/white-onion-flakes')['status']===200,'Publishing category restores products');
 $f=editor(req($url)['body']);$f['action']='delete_record';$r=req($url,$f);ok(str_contains($r['body'],'Move the products'),'Category with products cannot be accidentally deleted');
 $id=item_id(req('/admin/index.php?section=products')['body'],'White Onion Flakes');$url='/admin/index.php?section=products&edit='.$id;$f=editor(req($url)['body']);unset($f['featured']);req($url,$f);ok(!str_contains(req('/')['body'],'href="products/white-onion-flakes"'),'Unfeature product removes it from Home collection');$f=editor(req($url)['body']);$f['featured']='1';req($url,$f);ok(str_contains(req('/')['body'],'href="products/white-onion-flakes"'),'Feature product adds it to Home collection');
 ok(req('/admin/index.php?section=help')['status']===200,'Management guide is available');echo "\n$passed website manager checks passed.\n";
}finally{unlink($cookie);}
